"""Deterministic full-text candidate review from the existing candidate authority."""

import argparse
import difflib
import json

import yaml

from .editorial_candidates import review
from .locale import LocaleCatalog
from .paths import REPO_ROOT

OUTPUT = "docs/EDITORIAL_CANDIDATE_REVIEW.md"


def render():
    lines = [
        "# Editorial candidate review",
        "",
        "Generated by `python -m ocf_tools.editorial_review`; edit the linked authorities, not this document.",
        "",
        "All four proposals await explicit editorial approval. Preview is untimed; no generated audio has been listened to or approved. Historical provenance, rights clearance, and release approval are independent.",
        "",
    ]
    catalog = LocaleCatalog()
    for name in ("manifest-v2", "dissolve", "intuition", "clear-zone"):
        result = review(name)
        lines += [
            f"## {result['title']}",
            "",
            "### Identity and decision status",
            "",
            f"- Identity: `{result['function_id']}` ({result['registration']}).",
            "- Decision: draft awaiting review; production/release authorization: false.",
            f"- [Function authority](../{result['authority']})",
            f"- [Exact candidate narration](../{result['narration_authority']})",
            "",
        ]
        for command in result["commands"]:
            lines += [
                f"- `{command['id']}` — {command['role']} / {command['designation']}; display: `{command['display']}`; spoken: **{command['spoken']}**."
            ]
        lines += [
            "",
            "### Purpose, persistence and distinctive behavior",
            "",
            "```yaml",
            yaml.safe_dump(
                {"purpose": result["purpose"], "lifecycle": result["lifecycle"]},
                allow_unicode=True,
                sort_keys=False,
            ).rstrip(),
            "```",
            "",
            "### Activation and command procedures",
            "",
        ]
        for command in result["commands"]:
            lines += [
                f"#### {command['id']}",
                "",
                "```json",
                json.dumps(
                    {"procedure": command["procedure"], "resolved_steps": command["steps"]},
                    ensure_ascii=False,
                    indent=2,
                ),
                "```",
                "",
            ]
        if name == "intuition":
            lines += [
                "Proposed procedure (unreviewed): bring one question or situation into awareness; think or say Plus Intuition in the mind; allow a quiet moment to notice what arises; consider its meaning and choose a response with care and discernment. No breath hold, prescribed breathing pattern or eye closure is proposed. The procedure remains schema-status unresolved pending human review.",
                "",
            ]
        if name == "manifest-v2":
            lines += [
                "### Approved predecessor versus proposed revision",
                "",
                "The approved active predecessor remains selected. The following comparison shows changed lines only; the entire proposed narration follows.",
                "",
                "| Role | Approved current wording | Proposed revised wording |",
                "| --- | --- | --- |",
            ]
            for entry in result["entries"]:
                old = catalog.resource(entry["key"], "en-US", domain="narration", fallback=False)[
                    0
                ].text
                left, right = old.splitlines(), entry["text"].splitlines()
                changes = [
                    (a, b, c, d)
                    for tag, a, b, c, d in difflib.SequenceMatcher(a=left, b=right).get_opcodes()
                    if tag != "equal"
                ]

                def cell(parts):
                    return "<br>".join(parts).replace("|", "\\|") or "(none)"

                for a, b, c, d in changes:
                    lines.append(f"| {entry['role']} | {cell(left[a:b])} | {cell(right[c:d])} |")
            lines.append("")
        lines += ["### Full narration: authored references and resolved English", ""]
        for entry in result["entries"]:
            lines += [
                f"#### {result['title']}: {entry['role']}",
                "",
                f"Resource `{entry['key']}`, version `{entry['version']}`, status `{entry['status']}`; playback repetitions: {entry['repetitions']}.",
                "",
                "Authored template:",
                "",
                "```text",
                entry["raw_template"],
                "```",
                "",
                "Fully resolved spoken text:",
                "",
                "```text",
                entry["text"],
                "```",
                "",
                "Review/provenance notes:",
                "",
                entry["notes"] or "No additional entry notes supplied.",
                "",
            ]
        lines += ["### Review questions and approval boundary", ""]
        if name == "manifest-v2":
            lines += [
                "Existing approval covers the active predecessor and Plus Manifest cue, not this revised candidate. Decide whether to accept each revised passage before creating an active editorial successor. Historical-source classification does not transfer approval to newly authored passages."
            ]
        elif name == "intuition":
            lines += [
                "The opener was supplied previously. The entire body, closer and proposed procedure are newly AI-authored and unreviewed, not historical source wording. Review their intended behavior and exact procedure before registration. This is a complete staged proposal, not production narration."
            ]
        else:
            lines += [
                "Supplied original draft wording is retained exactly. Registration does not establish historical source verification, rights clearance or editorial approval. Review the intended behavior, command procedure and all narration before promotion."
            ]
        if name == "clear-zone":
            lines += [
                "Automatic is the baseline; primary restores/strengthens it. Observe pauses outward intention only. Suspend pauses the entire application. Overrides are mutually exclusive and end at normal sleep onset, loss of consciousness or deliberate primary invocation. These are instructional descriptions, not physical sensors or physiological triggers. Review these distinct roles and override semantics explicitly."
            ]
        lines += [
            "Listening and finished-session release remain pending. No approval is inferred from validation, cue expansion or this generated review.",
            "",
        ]
    return "\n".join(lines)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args(argv)
    path = REPO_ROOT / OUTPUT
    expected = render()
    if args.check:
        return int(not path.is_file() or path.read_text(encoding="utf-8") != expected)
    path.write_text(expected, encoding="utf-8", newline="\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
